PRAGMA foreign_keys=ON; PRAGMA journal_mode=DELETE;
 CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,minimum INTEGER NOT NULL CHECK(minimum>=0));
 CREATE TABLE IF NOT EXISTS schools(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);
 CREATE TABLE IF NOT EXISTS recipes(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);
 CREATE TABLE IF NOT EXISTS ingredients(recipe INTEGER REFERENCES recipes(id),item INTEGER REFERENCES items(id),grams INTEGER NOT NULL CHECK(grams>0),PRIMARY KEY(recipe,item));
 CREATE TABLE IF NOT EXISTS servings(id INTEGER PRIMARY KEY,date TEXT NOT NULL,school INTEGER REFERENCES schools(id),recipe INTEGER REFERENCES recipes(id),portions INTEGER NOT NULL CHECK(portions>0),created TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS movements(id INTEGER PRIMARY KEY,date TEXT NOT NULL,item INTEGER NOT NULL REFERENCES items(id),grams INTEGER NOT NULL CHECK(grams<>0),note TEXT NOT NULL,serving INTEGER REFERENCES servings(id),created TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE INDEX IF NOT EXISTS movement_dates ON movements(item,date);
 PRAGMA user_version=1;
